return items.map(item => {
  const dateStr = item.json.currentDate;
  const date = new Date(dateStr);
  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const year = date.getFullYear();
  return {
    json: {
      formattedDate: `${day}/${month}/${year}` // Add new property
    }
  }
});

const transcript = items[0].json.TRANSCRIPT || '';

// Split transcript into lines
const lines = transcript.split('\n').map(line => line.trim());

// Find the first non-empty line that contains meeting info (before "VIEW RECORDING")
let title = '';
for (const line of lines) {
  if (line.toLowerCase().includes('view recording')) break;
  if (line.length > 0) {
    title = line;
    break;
  }
}

return [{ json: { meetingTitle: title } }];

if (!items || !items[0] || !items[0].json || typeof items[0].json.TRANSCRIPT !== 'string') {
  throw new Error('Input TRANSCRIPT is missing or not a string');
}

const transcript = items[0].json.TRANSCRIPT;

const words = transcript.trim().split(/\s+/);
const totalWords = words.length;
const midpoint = Math.ceil(totalWords / 2);

const part1 = words.slice(0, midpoint).join(' ');
const part2 = words.slice(midpoint).join(' ');

// Return two separate JSON objects as two output items
return [
  { json: { part1: 1, text1: part1, totalWords } },
  { json: { part2: 2, text2: part2, totalWords } }
];

